mber","CrewDocument.lastCheckedOn","CrewCurrency.qualifiedUntil","FlightLeg.flightNumber","FlightLeg.estimated.arrival","FlightLeg.actual.blockOn","FlightLeg.aircraft.registration","RosterActivity.endsAt","RosterActivity.reportAt","Pairing.segments[].toStation","Pairing.segments[].startsAt","Pairing.segments[].endsAt","CrewNote.appliesFrom","CrewNote.text"],"probe":{"windows":[{"label":"Operated window","file":"scratchpad/unified-model-probe-past.out","dayFrom":17044,"dayTo":17074,"dateFrom":"2026-08-31","dateTo":"2026-09-30"},{"label":"Probe-day window","file":"scratchpad/unified-model-probe.out","dayFrom":17226,"dayTo":17256,"dateFrom":"2027-03-01","dateTo":"2027-03-31"}],"aggregates":[{"object":"vvROSTERID.SEX","values":["distinct values: \"2\"=3566, \"1\"=5781","distinct values: \"2\"=3566, \"1\"=5781"]},{"object":"vvROSTERID","values":["rows=9347 BIRTH non-null=9347 HOMEBASES_1 non-null=9347","rows=9347 BIRTH non-null=9347 HOMEBASES_1 non-null=9347"]},{"object":"vvCREWDB","values":["rows=9347 NATCOD=9131 NATCOD2=253 PHONE_1_NUMBER=8905 CITY=7394 RESIDENCECTR=8400 (non-empty counts)","rows=9347 NATCOD=9131 NATCOD2=253 PHONE_1_NUMBER=8905 CITY=7394 RESIDENCECTR=8400 (non-empty counts)"]},{"object":"CREWQUAL.PRIMARY_","values":["distinct: \"1\"=75987, \"0\"=115632","distinct: \"1\"=75987, \"0\"=115632"]},{"object":"CREWCAT","values":["rows=240 QUAL distinct=1 [\"0\"=240] ISFORECREW distinct=1","rows=240 QUAL distinct=1 [\"0\"=240] ISFORECREW distinct=1"]},{"object":"ROSTER","values":["rows=175648 GRDDUTYBEG\u003c>0=12398 GRDDUTYEND\u003c>0=12398 END\u003cBEG=0 DEBRIEFTIME\u003c>0=0 REPORTTIME\u003c>0=155 LEG_FLT\u003c0=82389","rows=820 GRDDUTYBEG\u003c>0=46 GRDDUTYEND\u003c>0=46 END\u003cBEG=0 DEBRIEFTIME\u003c>0=0 REPORTTIME\u003c>0=0 LEG_FLT\u003c0=820"]},{"object":"LEGMAIN","values":["rows=16000 FLT\u003c=0=0 ADLY\u003c>0=11792 AROUTE set=15412 REG set=15330 STA>=1440=2721","rows=14302 FLT\u003c=0=0 ADLY\u003c>0=0 AROUTE set=13909 REG set=0 STA>=1440=2641"]},{"object":"LEGMAIN","values":["ADATE-DAY distribution: 0=13130, -1=2280, -17046=28, -17051=28, -17050=28","ADATE-DAY distribution: 0=11878, -1=1953, -17228=34, -2=16, -17229=15"]},{"object":"LEGMAIN","values":["STD range by ADATE-DAY: -1:[0,1350] 0:[0,1439]","(not measured in this window)"]},{"object":"LEGTIMES","values":["rows=12344 FIRSTATD\u003c>0=0 ETA>=1440=2210 BLON>=1440=1121","rows=0 FIRSTATD\u003c>0=null ETA>=1440=null BLON>=1440=null"]},{"object":"CRROUTE","values":["distinct CROUTE=20074, CROUTE values with >1 CDATE=11769","distinct CROUTE=20074, CROUTE values with >1 CDATE=11769"]},{"object":"vvAIRCTYPE","values":["rows=26 AIRCTYPE rows=26 joined on ACTYPE=AIRCTYPE_ID=26 IATA agree=26","rows=26 AIRCTYPE rows=26 joined on ACTYPE=AIRCTYPE_ID=26 IATA agree=26"]}],"inventory":[{"object":"CREWDB","columns":6,"found":true},{"object":"vvCREWDB","columns":283,"found":true},{"object":"vvROSTERID","columns":239,"found":true},{"object":"ROSTERID","columns":18,"found":true},{"object":"CREWQUAL","columns":12,"found":true},{"object":"vvqualifications","columns":16,"found":true},{"object":"CREWCATEG","columns":4,"found":true},{"object":"CREWCAT","columns":4,"found":true},{"object":"vvPositions","columns":9,"found":true},{"object":"vvAIRCTYPE","columns":116,"found":true},{"object":"AIRCTYPE","columns":5,"found":true},{"object":"ROSTER","columns":52,"found":true},{"object":"ROSTERDT","columns":12,"found":true},{"object":"LOG_ROSTER","columns":28,"found":true},{"object":"LEGMAIN","columns":69,"found":true},{"object":"LEGTIMES","columns":31,"found":true},{"object":"LOG_LEGTIMES","columns":24,"found":true},{"object":"CRROUTE","columns":34,"found":true},{"object":"CREWLEG","columns":25,"found":true},{"object":"CRLEGGROUND","columns":11,"found":true},{"object":"vr_FlightMembers","columns":18,"found":true},{"object":"vr_Flifo_Legs","columns":24,"found":true},{"object":"vr_OSB_Delays","columns":44,"found":true},{"object":"vvCrewCodes","columns":67,"found":true},{"object":"CRCODES","columns":4,"found":true},{"object":"CREWCODES","columns":0,"found":false},{"object":"CARRIERS","columns":4,"found":true},{"object":"CREXPREC","columns":7,"found":true},{"object":"EXPI","columns":46,"found":true},{"object":"vvCountries","columns":55,"found":true},{"object":"vvAirports","columns":125,"found":true},{"object":"vvMCREW3","columns":14,"found":true},{"object":"PUBLLEGS","columns":34,"found":true},{"object":"ALERTCRW","columns":12,"found":true},{"object":"ALERTFLT","columns":13,"found":true},{"object":"LEGMEMO","columns":11,"found":true},{"object":"TABLES","columns":3,"found":true}]},"habits":[{"aims":"Dates are day numbers counted from 1980-01-01; times are minutes after midnight UTC.","unified":"Plain ISO dates (isoDate, each with a stated zone) and UTC instants (instant).","ev":"domains/airline/crew/adapters/src/aims/convert.ts:7-23"},{"aims":"A scheduled arrival after midnight is stored as minutes ≥ 1440 on the departure day (2,721 of 16,000 legs); ETA and BLON are stored the same way (2,210 and 1,121 of 12,344).","unified":"One scheduled / estimated / actual instant per event; the wrap is applied once in the adapter.","ev":"scratchpad/unified-model-probe-past.out:9, :12"},{"aims":"LEGMAIN.ADATE looks like the arrival day: it is DAY or DAY−1, plus small clusters of near-zero garbage values (28 rows each at −17046, −17051, −17050).","unified":"ADATE is read nowhere. Probe P11 refuted it: the 2,666 of 16,000 legs that land on the next UTC day still carry ADATE = DAY, and it is never DAY + 1. The arrival is DAY + STA (pre-wrapped) and the local departure date is computed in the origin station's zone.","ev":"scratchpad/unified-model-probe-past.out:10; scratchpad/unified/probes-0.6.out:56-104 (P11)"},{"aims":"ROSTER.LEG_FLT is a flight number when positive and a duty code when negative (82,389 of 175,648 rows negative).","unified":"RosterActivity.category (structural: flight, deadhead, ground_transfer, ground_duty, training, reserve, absence, leave, day_off, other) plus activityCode, which resolves to the ActivityCode catalogue (vvCrewCodes) and is mapped by tenant config.","ev":"scratchpad/unified-model-probe-past.out:8; unified-model-0.6.md §5"},{"aims":"ROSTER.REPORTTIME is almost never set (155 of 175,648 rows) and DEBRIEFTIME never (0).","unified":"Probe P9: CHECK_IN is set on 14,586 of 93,259 flight rows (at most one per crew, DUTYNO and DUTYDAY); CHECK_OUT and GRDDUTYBEG are 0 on every flight row. DutyPeriod.actualReportAt comes from CHECK_IN; actualReleaseAt has no AIMS source.","ev":"scratchpad/unified-model-probe-past.out:8; scratchpad/unified/probes-0.6.out:44-48 (P9)"},{"aims":"CRROUTE.CROUTE (the pairing number) is recycled: 11,769 of 20,074 numbers appear with more than one CDATE.","unified":"Pairing identity is the source ref; pairingNumber + startDate stay business fields. Probe P8 refuted the window rule for RosterActivity.pairingRef (50,131 of 93,259 flight rows match many pairings); the leg-key rule is defined, and zero or several matches is the named state roster_activity_pairing_ambiguous until P8b measures it.","ev":"scratchpad/unified-model-probe-past.out:13; scratchpad/unified/probes-0.6.out:41-42 (P8)"},{"aims":"ROSTER.DUTYDAY looks like the duty's day, and the shipped adapter and its comments treat it as agreeing with LEG_DAY.","unified":"It is a multi-day anchor of the line's DUTYNO (the pairing's first-leg day): 2 to 13 days before LEG_DAY on at least 12,615 of 93,259 flight rows (13.5%), probe P27. DutyPeriod.dutyDate is computed base-local from the duty's report instant, never copied (decision N5 asks for the check-in reads to be verified).","ev":"scratchpad/unified/probes-0.6.out:559-620 (P27)"},{"aims":"vvROSTERID.BIRTH and HIRE look like two text formats (yyyymmdd and ddmmyyyy).","unified":"They are one: every ddmmyyyy-shaped value also matches yyyymmdd (yyyymmdd + empty = 9,347 on both columns), so the decode is yyyymmdd only; an invalid value is crew_date_undecodable (probe P1).","ev":"scratchpad/unified/probes-0.6.out:2-3 (P1)"},{"aims":"CREXPREC rows of the \"90 Day\" EXPI kind were documented as document end dates with no currency source.","unified":"They are the T/O + landing currency: 2,673 records, 1,616 current (probe P25). CrewCurrency is produced from CREXPREC rows of tenant-configured currency kinds (EXPIDATE → qualifiedUntil, CHKLAST → lastQualifyingEventOn).","ev":"scratchpad/unified/probes-0.6.out:535-551 (P25)"},{"aims":"Deadhead (PAX) lives in two places with different retention: vr_FlightMembers (about three months) and CREWLEG.","unified":"RosterActivity.category = deadhead with travelModeSource; a defaulted value is a named state, not an operating leg.","ev":"unified-model-0.6.md §5"},{"aims":"Absences, reserve and vacation are all ROSTER rows with a negative LEG_FLT code, read today by three near-identical queries under three keys.","unified":"One RosterActivity read with a per-category population predicate; facets absence{}, reserve{}, leave{} hold what differed.","ev":"unified-model-0.6.md §5; domains/airline/crew/adapters/src/aims/reader.ts:494, :565, :1503"},{"aims":"A duty-code table named CREWCODES does not exist; CRCODES and vvCrewCodes do.","unified":"ActivityCode: one typed catalogue table (whole-day, time basis, default begin/duration, report/debrief offsets, effective dates) from vvCrewCodes, with the tenant meaning kept in config.","ev":"scratchpad/unified-model-probe.out:25-27"},{"aims":"LEGTIMES.FIRSTATD is 0 on all 12,344 operated legs.","unified":"firstActualDeparture is dropped: there is no source.","ev":"scratchpad/unified-model-probe-past.out:12"},{"aims":"CREWCAT.QUAL is 0 on all 240 categories.","unified":"CrewGroup becomes a scheme (crew_group) of CodeListEntry; its meaning (carrier, seniority list) stays tenant config.","ev":"scratchpad/unified-model-probe-past.out:7"},{"aims":"Two aircraft-type objects (vvAIRCTYPE and AIRCTYPE), 26 rows each, joined on ACTYPE = AIRCTYPE_ID with IATA codes agreeing on all 26.","unified":"One AircraftType catalogue table; the qualification-family rule stays Control Tower rule data.","ev":"scratchpad/unified-model-probe-past.out:14"},{"aims":"Every CREWDB crew is read as active today, former crew included.","unified":"CrewMember.employmentStatus carries an explicit unknown; a tenant ruling decides how consumers treat it.","ev":"knowledge-base/reference/canonical-to-aims-mapping.md:139-142"},{"aims":"Gender is vvROSTERID.SEX as \"1\" / \"2\" (5,781 / 3,566).","unified":"CrewMember.gender as an open string, tagged sensitive and sealed.","ev":"scratchpad/unified-model-probe-past.out:3"},{"aims":"Alert types and memo categories are source integers.","unified":"alertTypeCode / categoryCode strings that resolve to CodeListEntry schemes, plus a configRef for the tenant policy (G1, R13).","ev":"unified-model-0.6.md §3"},{"aims":"Fixed-width nchar text arrives padded with spaces.","unified":"Every text read is trimmed (rtrim) in the adapter.","ev":"field transforms in unified-model-0.6.json"},{"aims":"vvCREWDB is a 283-column view that also holds SOCIALSECRTY, BANKACC and CREDITNUM.","unified":"The adapter selects explicit columns only; those three are never read.","ev":"scratchpad/unified-model-probe.out:3"}],"rules":[{"id":"R1","name":"Explicit path","text":"The column copies one named leaf, never a container.","fails":"payload->'airline'","source":"blueprint 0.5 §4.1 (1025951c)"},{"id":"R2","name":"Tag","text":"The leaf is explicitly pii.none in the read entity (untagged fails, §4.6).","fails":"FlightMemo.text (domains/airline/crew/canonical/src/index.ts:311)","source":"blueprint 0.5 §4.1 (1025951c)"},{"id":"R3","name":"Row class","text":"The row has no data subject, or a recorded security ruling names this (entity, column). The A2 ruling covers effective_date only (security-signoff-a2-promoted-date-erasure.md:197-201).","fails":"any non-envelope column on a B/C table","source":"blueprint 0.5 §4.1 (1025951c)"},{"id":"R4","name":"Link","text":"Not a reference into a subject-bearing entity unless an R3 ruling covers it.","fails":"CoverageDemand stored origin.absenceRef (domains/airline/crew/canonical/src/upsert.ts:85; read path origin.absenceId, index.ts:910)","source":"blueprint 0.5 §4.1 (1025951c)"},{"id":"R5","name":"Source ids","text":"No column holds a subject's source key; identity_mapping survives erasure (security-signoff-a2-promoted-date-erasure.md:116-122).","fails":"crewMemberRef.sourceId","source":"blueprint 0.5 §4.1 (1025951c)"},{"id":"R6","name":"No free text","text":", even pii.none.","fails":"FlightAlert.alertLabel, CoverageDemand.routeDesc","source":"blueprint 0.5 §4.1 (1025951c)"},{"id":"R7","name":"Erasable","text":"On a subject-bearing table every spine column is nulled by erasure and nullable (§3.5).","fails":"","source":"blueprint 0.5 §4.1 (1025951c)"},{"id":"R8","name":"Backups","text":"An R3 ruling states its position on backups and replicas.","fails":"","source":"blueprint 0.5 §4.1 (1025951c)"},{"id":"R9","name":"No catch-all columns","text":"(ruling 16, kept by ruling 17). No extensions, attributes or map column and no jsonb spine column; the only jsonb column is the sealed payload. Every spine column is an explicit path (R1). Read as a model rule too: the newly proposed map's extensions, CrewGroup.attributes, CodeListEntry.attributes and CrewDocument.appliesTo are dropped or made explicit (appliesToCountries), and the current Pairing.requiredComplement record becomes an explicit array (domains/airline/crew/canonical/src/index.ts:464-471).","fails":"a jsonb column holding airline; a z.record field","source":"blueprint 0.5 §4.1 (1025951c)"},{"id":"R10","name":"No foreign keys between entity tables","text":"(ruling 16, kept by ruling 17). A reference stays a {system, sourceId} ref resolved to a canonicalId (§4.4.1); the only foreign key on an entity table is \u003ct>_indexed → entities.canonical_index (§3.2). Ref types are checked at write (§5.4), not by the database. Where the target is config or a global natural key, the model holds a value, not a ref: ISO country codes, carrier designators, aircraft type codes, position codes, station IATA codes (the Station.iata precedent, domains/airline/shared/canonical/src/base.ts:43).","fails":"flight_alert.flight_leg_id REFERENCES entities.flight_leg; a countryRef to Country","source":"blueprint 0.5 §4.1 (1025951c)"},{"id":"R11","name":"The roster line carries the plan; the leg carries the operation","text":"No entity but FlightLeg stores a leg's estimates, actuals or status; a roster line, a pairing segment or a demand leg holds a flightLegRef and its own rostered times only. Copying leg times is how T6.4 shipped: the estimated arrival was never carried across (domains/airline/crew/canonical/src/index.ts:338-345). A review rule; no gate checks it mechanically.","fails":"a RosterActivity estimatedArrival","source":"blueprint 0.5 §4.1 (1025951c)"},{"id":"R12","name":"Customer vocabulary is a code plus a config ref; a closed enum only where the platform branches","text":"(G1, CR003-D3/D4). A structural classification the platform branches on stays a closed zod enum (activityKind, qualificationType, dutyKind, derivation, phase, channel, employmentStatus, holdingStatus, purpose); a source or airline vocabulary is a string code with a …ConfigRef (activityCode, delayCode, documentTypeCode, groupCode, purposeCode, qualificationCode, alertTypeCode, categoryCode). In 0.6 the structural discriminator on RosterActivity is category (replacing activityKind and travelMode).","fails":"the newly proposed map's activityType \"RESERVE / ABSENCE\"; the current FlightAlert.alertType source integer","source":"blueprint 0.5 §4.1 (1025951c)"},{"id":"R13","name":"Catalogue is data, meaning is policy","text":"The catalogue of a source's codes and reference rows (carriers, aircraft types, positions, activity codes, document types, label-only code lists) is DATA: synced from the source, effective-dated where the source dates it, tenant-scoped (tenant_id, FORCE RLS), class A, an entity table. The MEANING a tenant attaches to a code — what the platform branches on (category, classification, eligibility group, scope), or regulatory/contractual semantics — stays tenant config or Control Tower rule data. A referencing field holds the code as a VALUE (R10), which resolves to the catalogue row (asOf the field's date where the catalogue is dated), plus a …ConfigRef that is the tenant policy key — stored where the policy list depends on the row (a roster line's category decides which list) or a mapping can miss (…:unmapped); where the list is fixed and the key a pure function of the code, the code is the key (position codes → positionConfigs: CR003-D3's code + tenant-config pattern, without a stored positionConfigRef that only repeats the code). No field holds both a code and a ref to the same catalogue row (redundant links can disagree). A list whose attributes the platform reads gets its own typed table; label-only lists share CodeListEntry with a typed scheme. A mapping miss is written \u003cprefix>:\u003clist>:unmapped and counted as config_ref_unmapped (one series per entity_type and list); the activity-category mapping alone refuses instead (ruling 0.7-1).","fails":"a field holding both a carrier code and a Carrier ref; a catalogue left in tenant config so nothing validates against it","source":"unified model 0.6 (modelRules06)"},{"id":"R14","name":"Every date says which day","text":"Every isoDate field states its zone: utc-day, station-local-day or base-local-day; every instant is utc-instant. The zone is the field's DEFINITION; a producer whose source day has another or unknown zone converts or refuses (named state), never relabels (the N-OC UTC-midnight relabelling, review N3c). Amended in 0.7 (lens 1 #8, decision N8): where a source states a calendar day without a zone, the field carries a recorded approximation (zoneApproximation: the zone the producer assumes, the bounded error, and the named state that counts where the approximation can be wrong); an approximation is never silent and never a relabelling of an instant. Amended again in 0.8 (lens 1 #8): a day stated in a source's company calendar is a fifth zone, source-calendar-day, with its tz per source system in tenants/\u003cid>/rules/policy/source-calendars.json; it is never stored as base-local (that would be the relabelling this rule forbids). An undated AIMS base is dated by observation (CrewBaseAssignment.validFrom = the day the platform first saw it), so a base transfer re-computes dutyDate only from the day it was seen, never for history.","fails":"an isoDate field with no zone; a producer relabelling a UTC day as base-local","source":"unified model 0.6 (modelRules06)"}],"binding":[{"name":"Sealed bodies","text":"Every body is sealed in every class: subject rows under the subject's key (DEK), others under the global cipher. The spine is a promoted copy extracted before sealing; reads decrypt the body and never reassemble from spine columns.","ev":"blueprint §3.4"},{"name":"Typed spine only on subject-less tables, with one exception","text":"Spine columns exist on class A tables and FlightMemo; this includes the six catalogue tables of 0.6 (codes, scheme, sourceCrewClass). Every crew-linked table (class B, C or varies) is envelope-only with a sealed body, except RosterActivity.category: the one clear spine column on a crew table, an explicit R3 exception (ruling 0.6-2, evidence P32) because the category alone is not personal and the health detail stays in the sealed absence facet.","ev":"ruling 11; rulings 0.6-2 and 0.6-9; unified-model-0.6.md §9"},{"name":"No catch-all columns (R9)","text":"The newly proposed extensions column, CrewGroup.attributes, CodeListEntry.attributes and CrewDocument.appliesTo are dropped or made explicit; the current Pairing.requiredComplement becomes an explicit array of {positionCode, count}. CodeListEntry has a typed scheme column and no attributes map.","ev":"unified-model-0.6.md §3"},{"name":"No cross-entity foreign keys (R10)","text":"Links are refs resolved to canonical ids (crewMemberRef, flightLegRef, pairingRef, dutyPeriodRef, evidenceRef, parentDocumentRef) or plain values when the target is a global natural key or a catalogue code (ISO country, carrier, aircraft type, position code, station IATA). A catalogue code is a value that resolves to the catalogue row (R13), never a ref beside it.","ev":"unified-model-0.6.md §3 (R10, R13)"},{"name":"Codes as strings plus catalogue link plus config ref (R12, R13)","text":"Structural enums the platform branches on stay closed (category, qualificationType, dutyKind, phase, channel, employmentStatus, holdingStatus). Customer vocabulary is a code string that resolves to a catalogue table (Carrier, AircraftType, CrewPosition, CodeListEntry, ActivityCode, DocumentType) plus, where the policy list depends on the row or a mapping can miss, a …ConfigRef that is the tenant policy key. Position codes carry no stored ref: the code is the key.","ev":"G1, CR003-D3/D4; unified-model-0.6.md §3"},{"name":"CR003-D1 and the 2026-07-18 VacationBlock ruling: overturned in 0.6","text":"By the operator ruling of 2026-10-02, Absence, ReserveBlock and VacationBlock are merged into RosterActivity as a structural category with absence, reserve and leave facets. RosterActivity(category = reserve) is the single authority on reserve availability; DutyPeriod still excludes absence and reserve. The entity types and prefixes abs, rsv, vac are retired.","ev":"unified-model-0.6.md §5, §9"},{"name":"Every date says which day (R14)","text":"All 34 isoDate fields state utc-day, station-local-day or base-local-day; all 46 instants are utc-instant. A producer whose source day has another or unknown zone converts or refuses (a named state), never relabels. Probes moved two definitions: Pairing.startDate/endDate are utc-day (CDATE and ENDDATE are the first and last leg's UTC day, P28 and P16) and DutyPeriod.dutyDate is computed base-local (DUTYDAY is a pairing anchor, P27).","ev":"unified-model-0.6.md §7"},{"name":"Never hard-delete (CR003-E2)","text":"Removal is lifecycle = retracted; the app role is granted SELECT, INSERT, UPDATE and never DELETE. The newly proposed recordStatus DELETED and CREWLEG.REMOVED map to retracted.","ev":"blueprint §3.3; standardColumns.lifecycle"},{"name":"Named fail-closed states","text":"Where the source cannot settle a value, the row carries a named state that consumers must handle, instead of a silent default. The list is below.","ev":"unified-model-0.6.md §3, §6"}],"failClosed":[{"path":"Pairing.complementStatus","value":"undecodable","since":"kept","meaning":"The complement could not be decoded; no shortage is computed from it."},{"path":"CrewDocument.expiryDateSource","value":"derived","since":"kept","meaning":"A derived expiry is never presented as recorded."},{"path":"OpenTime.awardHolderStatus","value":"unresolved","since":"kept","meaning":"The award holder could not be resolved to a crew member."},{"path":"CrewRequest.decisionStatus","value":"undecodable","since":"kept","meaning":"The source decision could not be decoded."},{"path":"CrewCurrency.currencyStatus","value":"indeterminate","since":"kept","meaning":"Currency cannot be judged from the data held."},{"path":"FdpExtension.status","value":"undecodable","since":"kept","meaning":"The extension status could not be decoded."},{"path":"CrewMember.employmentStatus","value":"unknown","since":"new in 0.5","meaning":"Today every CREWDB row is read as active, former crew included; unknown names that gap."},{"path":"RosterActivity.travelModeSource","value":"defaulted","since":"new in 0.5","meaning":"Neither PAX source held the row, so operating was assumed; distinguishable from a recorded operating leg."},{"path":"Pairing.baseSource","value":"inferred_first_departure","since":"new in 0.5","meaning":"The base is a proxy from the earliest departure, not a source fact."},{"path":"CrewBaseAssignment.validFromSource","value":"assumed_before_observation","since":"new in 0.9","meaning":"AIMS bases are undated: the first observed base is assumed back to the start of history (ruling 0.9-1), never presented as a dated source fact."},{"path":"FlightLeg.statusSource","value":"defaulted","since":"new in 0.6","meaning":"A stored scheduled status is a default even when actual times are present; defaulted names it."},{"path":"RosterActivity (row state)","value":"roster_activity_leg_unresolved","since":"new in 0.5","meaning":"A roster line whose leg is not in canonical parks as a named, counted state; legality never silently under-counts a duty."},{"path":"RosterActivity (row state)","value":"roster_activity_interval_invalid","since":"new in 0.6","meaning":"An endsAt at or before startsAt is refused, never wrapped to the next day (END \u003c BEG measured 0)."},{"path":"RosterActivity producer","value":"roster_log_operation_unknown","since":"new in 0.6","meaning":"A LOG_ROSTER DBOPERATION outside {2, 3, 4} is counted instead of silently read as an update (probe P34)."},{"path":"FlightLeg (row state)","value":"flight_leg_carrier_unresolved","since":"new in 0.6","meaning":"A carrier that does not resolve to the Carrier catalogue is named, instead of today's silent \"CM\" at 13 sites."},{"path":"CrewPosition (drift state)","value":"position_group_disagrees_with_source","since":"new in 0.6","meaning":"The tenant eligibility group disagrees with the source cockpit/cabin class (CK_CB); counted and alerted."},{"path":"Control Tower seam","value":"docrule_type_unknown","since":"new in 0.6","meaning":"A docrule names a document-type code the source catalogue does not have."},{"path":"Control Tower seam","value":"document_type_without_rule","since":"new in 0.6","meaning":"Crew hold documents of a kind no rule covers; never treated as compliant. Currency kinds are excluded (probe P25)."},{"path":"CrewMember.birthDate, hireDate (row state)","value":"crew_date_undecodable","since":"new in 0.6","meaning":"A non-empty BIRTH or HIRE that is not a valid yyyymmdd date: the field is absent and counted; measured volume 0 (probe P1)."},{"path":"CrewMember.nationalities (row state)","value":"crew_nationality_unresolved","since":"new in 0.6","meaning":"A NATCOD or NATCOD2 value that resolves to no ISO country: that value is absent and counted (299 of 9,131 measured, probe P2)."},{"path":"CrewMember.employmentStatus (counter)","value":"crew_employment_status_unknown_total","since":"new in 0.6","meaning":"Counts crew written with employmentStatus unknown, so the gap is visible while no AIMS source exists (probe P5)."},{"path":"ContactPoint.channel (row state)","value":"contact_kind_unmapped","since":"new in 0.6","meaning":"A phone COMKIND with no tenant mapping to voice, sms or whatsapp: that point is refused and counted (probe P7)."},{"path":"CrewGroupMembership (producer state)","value":"crew_group_unmapped_skipped","since":"new in 0.6","meaning":"A CREWCATEG category the tenant maps to no purpose is skipped and counted, never stored: the catalogue holds trade-union and health categories (probe P21, decision N4)."},{"path":"RosterActivity.pairingRef (row state)","value":"roster_activity_pairing_ambiguous","since":"new in 0.6","meaning":"Zero or several pairings match a flight line by the leg-key rule: pairingRef is absent, counted and alerted (probe P8; P8b measures the rate)."},{"path":"RosterActivity.dutyDate (row state)","value":"base_unknown","since":"new in 0.6","meaning":"No base is valid for the crew on that day, so the base-local day cannot be computed: refused and counted (probe P27)."},{"path":"CrewPosition (producer state)","value":"position_code_blank","since":"new in 0.6","meaning":"A ROSTER or CREWQUAL position pointing at a blank vvPositions row (15 of 24 rows are blank) is refused and counted (probe P29)."},{"path":"Carrier (row state)","value":"carrier_without_designator","since":"new in 0.6","meaning":"A CARRIERS row with no IATA or ICAO designator (TBA, COP and PSC are internal codes) is refused unless a tenant mapping names it (probe P30, decision N6)."},{"path":"AircraftType.validTo (row state)","value":"aircraft_type_inactive_undated","since":"new in 0.6","meaning":"INACTIVEDATE = -1 marks an inactive type with no date: validTo is not invented; the row is kept and counted (2 rows, probe P23)."},{"path":"ActivityCode.timeBasis (row state)","value":"activity_code_time_basis_unknown","since":"new in 0.6","meaning":"BEG_UTC_LCL is 0 on all 600 codes and 0 is not self-describing: the producer writes unknown and counts it until P26b decodes it."},{"path":"DocumentType.sourceDueUnit (row state)","value":"document_type_due_unit_unknown","since":"new in 0.6","meaning":"An EXPI DAYTYP other than 1 (days) or 2 (months): unit unknown, counted (probes P22, P25)."},{"path":"CrewCurrency (counter)","value":"crew_currency_indeterminate_total","since":"new in 0.6","meaning":"EXPIDATE is 0 or undecodable on a configured currency kind: currencyStatus is indeterminate and counted (probe P25)."},{"path":"CrewCurrency (gauge)","value":"crew_currency_requirements_unsourced","since":"new in 0.6","meaning":"A declared requirement with zero source records: it would fire today for an E190 requirement, because \"90d E9\" has 0 current records (probe P25)."},{"path":"CrewCurrency (boot seam)","value":"currency_kind_not_in_catalogue","since":"new in 0.6","meaning":"A configured currency kind missing from the DocumentType catalogue: counted and alerted at boot (probe P25, decision N2)."},{"path":"RosterActivity (producer state)","value":"roster_line_missing_vs_flight_members","since":"new in 0.6","meaning":"A vr_FlightMembers line with no ROSTER row, counted by the shadow parity: 81 in 30 days (0.09%, probe P10)."}],"ddlColumns":[["tenant_id","text NOT NULL","Defaults to the app.current_tenant GUC; FORCE RLS with the tenant_isolation policy. First column of the primary key; CHECK \u003c> ''."],["canonical_id","text NOT NULL","The \u003cprefix>_… id; primary key (tenant_id, canonical_id)."],["entity_type","text NOT NULL","A constant per table (CHECK = the entity type); the composite FK \u003ct>_indexed (tenant_id, canonical_id, entity_type) → entities.canonical_index is the only FK."],["payload","jsonb NOT NULL","The sealed body (ciphertext). The only jsonb column and the only source of truth for reads. STORAGE EXTERNAL on [large] tables."],["source_change_version","text NOT NULL","Source change watermark used for idempotent upserts."],["lifecycle","text NOT NULL","CHECK IN ('active','superseded','retracted'); never hard-delete (CR003-E2)."],["data_mode","text NOT NULL","CHECK IN ('live','simulated') (CR003-E5)."],["subject_kind / subject_id","text, text","Both NULL on subject-less rows (class A); \u003ct>_subject_pair CHECK forbids a half-set subject; no default kind."],["effective_date","date","The promoted business date on [dated] tables; on an undated table \u003ct>_no_effective_date refuses a value."],["content_fingerprint","bytea","Change detection without decrypting the body."],["updated_at","timestamptz NOT NULL","Platform write instant (default now())."],["spine columns","typed, nullable","Class A tables and FlightMemo only (ruling 11). Each passes R1–R10; a required one carries a _present CHECK so erasure can still null it."]],"ddlSql":"CREATE TABLE IF NOT EXISTS entities.\u003ct> (\n  tenant_id             text        NOT NULL DEFAULT current_setting('app.current_tenant', true),\n  canonical_id          text        NOT NULL,\n  entity_type           text        NOT NULL,\n  payload               jsonb       STORAGE EXTERNAL NOT NULL,  -- STORAGE on [large] only; sealed body, ciphertext does not compress (dba)\n  source_change_version text        NOT NULL,\n  lifecycle             text        NOT NULL,\n  data_mode             text        NOT NULL,\n  subject_kind          text,                                    -- no default: the platform names no kind\n  subject_id            text,\n  effective_date        date,\n  content_fingerprint   bytea,\n  updated_at            timestamptz NOT NULL DEFAULT now(),\n  -- spine columns for this table (§4.4), each nullable\n  CONSTRAINT \u003ct>_pkey               PRIMARY KEY (tenant_id, canonical_id),\n  CONSTRAINT \u003ct>_indexed            FOREIGN KEY (tenant_id, canonical_id, entity_type)\n                                    REFERENCES entities.canonical_index (tenant_id, canonical_id, entity_type),\n  CONSTRAINT \u003ct>_entity_type_check  CHECK (entity_type = '\u003cType>'),\n  CONSTRAINT \u003ct>_tenant_set         CHECK (tenant_id \u003c> ''),\n  CONSTRAINT \u003ct>_lifecycle_check    CHECK (lifecycle IN ('active','superseded','retracted')),\n  CONSTRAINT \u003ct>_data_mode_check    CHECK (data_mode IN ('live','simulated')),\n  CONSTRAINT \u003ct>_subject_pair       CHECK ((subject_id IS NULL) = (subject_kind IS NULL))\n  -- [undated] only:                 CONSTRAINT \u003ct>_no_effective_date CHECK (effective_date IS NULL)\n  -- one per required spine column:  CONSTRAINT \u003ct>_\u003ccol>_present CHECK (lifecycle = 'retracted' OR \u003ccol> IS NOT NULL)\n  -- one per non-enum and enum spine rule (§4.5): CONSTRAINT \u003ct>_\u003ccol>_check CHECK (\u003ccol> IS NULL OR …)\n) WITH (fillfactor = 90\n        -- [large] only: , autovacuum_vacuum_scale_factor = 0.05, autovacuum_analyze_scale_factor = 0.02,\n        --               toast.autovacuum_vacuum_scale_factor = 0.05\n);\nCREATE INDEX IF NOT EXISTS \u003ct>_subject_idx ON entities.\u003ct> (tenant_id, subject_kind, subject_id)\n  WHERE subject_id IS NOT NULL;\n-- [dated] only (the descriptor maps a business date): windowed reads and countUndated\nCREATE INDEX IF NOT EXISTS \u003ct>_effective_date_idx ON entities.\u003ct> (tenant_id, effective_date)\n  WHERE effective_date IS NOT NULL AND lifecycle = 'active';\nCREATE INDEX IF NOT EXISTS \u003ct>_undated_idx ON entities.\u003ct> (tenant_id, data_mode)\n  WHERE effective_date IS NULL AND lifecycle = 'active';","neverRead":[{"object":"vvCREWDB","column":"SOCIALSECRTY","why":"Government identifier (social security number). No field maps it; reading it would put a national id into the platform.","inInventory":true},{"object":"vvCREWDB","column":"BANKACC","why":"Bank account number. Financial data with no consumer.","inInventory":true},{"object":"vvCREWDB","column":"CREDITNUM","why":"Card number. Financial data with no consumer.","inInventory":true}],"blueprintCommit":"1025951c"}</script>
knowledge-base/reference/canonical-data-map.html:17619:<script type="application/json" id="derived-data">{"current":["Airport","CrewMember","CrewCurrency","DocumentExpiry","FlightLeg","FlightAlert","FlightMemo","FlightDisruptionState","PaxImpactRecord","CrewDutySegment","CrewCheckIn","CrewLegAssignment","CrRouteAssignment","DutyPeriod","Absence","ReserveBlock","VacationBlock","Pairing","ConnectionLeg","OpenTime","CrewRequest","CoverageDemand","FdpExtension","NearbyStationPresence","CrewAlert"],"proposed":["Qualification","CrewGroupMembership","CrewGroup","CrewDocument","DocumentType","CrewMember","ContactPoint","Address","CrewBaseAssignment","CrewNote","ChangeEvent","RosterActivity","DutyPeriod","Pairing","PairingSegment","FlightLeg","FlightDelay","EntryRequirement","CrewComplementRequirement","Airport","Country","Carrier","Aircraft","AircraftType","CrewPosition","CodeListEntry"],"changes":{"rosterDiffs":[["Absence event lifecycle (crew.absence_reported / _retracted from LOG_ROSTER)","Absence entity","Behaviour of RosterActivity lines with category = absence; natural key and payload unchanged"],["Sick-call demand source (affectedFlightLegRefs, written by a later enrichment)","Absence","absence.affectedFlightLegRefs"],["Classification (unplanned, fatigueRelated, healthRelated: sensitive)","Absence","absence.classification.*, leaf-tagged; RosterActivity becomes class C (still sealed under the crew key)"],["Reserve class and ReserveClassConfig (cascade, windows, fairness) used by Forge prep","ReserveBlock","reserve.classCode + reserve.classConfigRef; the contactable window stays computed by Forge (CR003-E6, not overturned)"],["Reserve rostered position (callout gate)","ReserveBlock upsert only","The line's positionCode"],["Vacation floor-reduction meaning and month-wide refresh window","VacationBlock and its own refresh","leave.classConfigRef → tenant leave classes; the roster read window for category = leave"],["Population scope: absence ignores crew bases, reserve and vacation scope by base","Three reads","One read with a per-category population predicate"]],"mergeReasons":[["One source fact, already one read.","All three are ROSTER rows with a negative LEG_FLT code (82,389 of 175,648 rows in the operated window); the adapter already reads them with one generic SQL under three keys; N-OC models every line as a RosterActivity. Keeping them apart needed a router, a refusal state and a critical alert whose only job was to defend the split."],["Every protection the split bought survives.","healthRelated exists only under absence.classification, so non-absence lines have nothing to scrub; reserve authority is one closed enum value validated at write; reserve and leave are distinct enum values with a read-plane test pinning the filter; DutyPeriod still excludes absence and reserve, so the CR003-D1 blocker is not reintroduced."],["It removes defects and gains capabilities.","Completeness is one query instead of a four-entity union; airport standby can attach to a DutyPeriod; absence lines gain the rostered position; the fabricated occurredAt of crew.absence_reported becomes the log row's own time (absence.reportedAt); one day definition (base-local dutyDate)."]],"catalogue":[["Carrier","AIMS CARRIERS (ID, CODE); N-OC AirlineCode / ICAOAirlineCode","tenant subsidiary.carriers {designator, relationship own | affiliate | partner, inOperatingScope}, keyed by designator"],["AircraftType","AIMS vvAIRCTYPE (26 rows); N-OC GetAircrafts distinct Type","qualification-family rule (Control Tower) and freighter/scope exclusion (tenant config), keyed by type code"],["CrewPosition","AIMS vvPositions (CODE, DESC_, CK_CB, RANK, ALTRN); N-OC Ranks","tenant positionConfigs (group, floatOrder, labels, isCommand) keyed by position code; canOperateAs in rule data"],["CodeListEntry","AIMS vvALERTYPE, vvFlightMemoCateg, DLYCD, CREWCAT, distinct LEGMAIN.CNXREASON / FLTYPE, PHONE_n_COMKIND; N-OC REASON","per scheme, the tenant config the referencing field's …ConfigRef names"],["CrewGroup (a scheme of CodeListEntry)","AIMS CREWCAT (240 rows; label only)","carrier (78 = CM, 79 = P5, 94 = Wingo), seniority list, special-airport category: tenant config"],["ActivityCode","AIMS vvCrewCodes (ID is the negative ROSTER.LEG_FLT marker); N-OC REFERENCE_ACTIVITY","tenant activity mapping (code → category, absence classification, reserve class, leave class) via RosterActivity.activityConfigRef"],["DocumentType","AIMS EXPI (SHORTDESC, DESC_, SEVERITY, MINDUE, MAXDUE, DAYTYP, EFFECTIVE_BEG/END)","Control Tower docrules: hasExpiry, grace, renewal lead, blocksDutyWhenInvalid, isTravelDocument, tier, action; keyed by the catalogue code"]],"newRulings":[["Six catalogue entity tables","Carrier, AircraftType, CrewPosition, CodeListEntry, ActivityCode, DocumentType. Amends ruling 17's entity set from 29 tables to 32 and reverses blueprint 0.5 §4.8's config / rule-data line for these names."],["R3 security ruling for roster_activity.category","One clear column (ruling 11 asks per entity and column), or the explicit choice of decrypt-and-filter reads (about 5,900 code lines a day at Copa, about 170 of them reserve, measured by P32). Ruled: the clear column (0.6-2)."],["RosterActivity subject class B → C","It now holds the sensitive absence.classification.healthRelated. No storage change: every crew-linked body is sealed under the crew key either way."],["dutyDate defined base-local","On RosterActivity and DutyPeriod. On AIMS this changes the date of a night duty relative to today's CrewDutySegment (the leg's UTC day); the legality differential must prove the verdicts before cutover. P27 showed AIMS has no per-duty day to copy (DUTYDAY is a pairing anchor), so the value is computed on AIMS whatever its zone."],["Pairing identity = the source ref","pairingNumber + startDate stay business fields and spine columns. P8 and P28: (CDATE, CROUTE) is the AIMS identity grammar; startDate is a UTC day (decision N1)."],["FlightLeg.estimated.source values renamed","aeroapi → external_feed; read planes that print the provenance change."],["CrewAlert.isLegalityType removed","Resolved per alert type through alertTypeConfigRef (7 non-test files)."],["DutyPeriod.pairingRef removed","New in 0.5, so no standing decision is overturned."],["Spine set re-opened again (open decision 9)","Spine columns on the six catalogue tables (codes, scheme, sourceCrewClass)."],["No stored positionConfigRef on position fields","Qualification, RosterActivity, OpenTime, CoverageDemand and others: the position policy key is the code (R13). Records what 0.5 did silently when it split CrewMember.positions."]],"stillOpen":"Ruled on 2026-10-02 (\"go with your recommendations on the rulings\"): the ten 0.6 overturns and the seven carried 0.5 decisions are listed under Rulings. Two are not final: 0.5-4 (sense_noc on the one-time reset) is deferred until the N-OC namespacing PR measures, and 0.5-8 (CrewNote) is stored but the security sign-off is still owed. The seven new decisions N1 to N7 that the probe results raised have recommendations and no ruling yet. Confirmed, not overturned: the operator instruction of 2026-09-19 that position groups stay tenant config.","fold":[["CrewCurrency now has an AIMS producer","Supersedes the adapter refusal (MssqlAimsDb.getCrewCurrency, domains/airline/crew/adapters/src/aims/mssqlDb.ts:1499-1515) and the \"no verified source\" KB section. The producer reads CREXPREC rows of the EXPI kinds the tenant configures as currency kinds (Copa: \"90 Day\", T/O + landing currency, 2,673 records, 1,616 current; \"90d E9\" has 4 records, 0 current). EXPIDATE becomes qualifiedUntil and CHKLAST becomes the new field lastQualifyingEventOn (a day, so not written into the instant lastEventAt). vvCREWDB.LASTACDAY_n is not a source (0 for every crew). A follow-up adapter change wires the read and the seeded alarms.","P25, P20; decision N2"],["ADATE is not read","LEGMAIN.ADATE is neither the arrival day nor a local date: the 2,666 of 16,000 legs that land on the next UTC day still carry ADATE = DAY, and it is never DAY + 1. FlightLeg.scheduled.arrival is DAY + STA (pre-wrapped) and FlightLeg.localDepartureDate is computed from scheduled.departure in the origin station's zone. No field is sourced from ADATE.","P11"],["Pairing.startDate and endDate are UTC days from CDATE","Their dateZone is redefined from base-local-day to utc-day: CDATE is the first leg's UTC day (delta 0 on 12,154 pairings in every departure hour, never negative) and ENDDATE is the last leg's UTC day (10,568 of 12,543 in the window). A base-local pairing day would be computed from the optional, inferred Pairing.base, and no regime counts pairing days; duty days keep the base-local rule.","P28, P16; decision N1"],["DutyPeriod.dutyDate is computed base-local","ROSTER.DUTYDAY is a pairing anchor, not a per-duty day: it is 2 to 13 days before LEG_DAY on at least 12,615 of 93,259 flight rows (13.5%). dutyDate is the base-local day of the duty's report, in the zone of the crew's base valid that day, and is never copied from DUTYDAY. Ruling 0.6-4 (base-local) stands and is now evidenced.","P27; ruling 0.6-4; decision N5"],["Birth and hire dates decode as yyyymmdd only","BIRTH and HIRE are not two formats: every ddmmyyyy-shaped value also matches yyyymmdd (yyyymmdd + empty = 9,347 on both columns). Accepting ddmmyyyy as well would mis-read real dates. An invalid value is the named state crew_date_undecodable (field absent, counted; measured volume 0).","P1"],["RosterActivity.category is the one sanctioned clear spine column on a crew table","An explicit R3 exception (ruling 0.6-2): the category value alone is not personal (closed structural enum, no free text, not a link, nullable and nulled by erasure); the health detail stays in the sealed absence facet. Evidence: without a clear column a reserve read would decrypt about 5,900 code lines a day to keep about 170. Every other table with a data subject stays envelope-only.","P32; ruling 